package com.ticketing.v3.performance.service;
import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import com.ticketing.v3.performance.repository.ManagementRepository;import com.ticketing.v3.venue.service.VenueService;import com.ticketing.v3.seat.service.InventoryService;import com.ticketing.v3.global.exception.ApiException;import java.util.*;import java.time.*;import java.sql.Timestamp;
@Service public class PerformanceService {
 private final ManagementRepository performances;private final VenueService venues;private final InventoryService inventory;private final Clock clock;
 public PerformanceService(ManagementRepository p,VenueService v,InventoryService i,Clock c){performances=p;venues=v;inventory=i;clock=c;}
 public record CreatePerformance(String title,String description,long venueId){}
 public record CreateSession(Instant startsAt,Long priceKrw){}
 public record Sale(String status,Instant startsAt,Instant endsAt){}
 public Map<String,Object> find(long id){return performances.find(id,false).orElseThrow(ApiException::missing);}
 private Map<String,Object> owned(long user,long id){var p=performances.find(id,true).orElseThrow(ApiException::missing);if(p.get("ownerId")==null||((Number)p.get("ownerId")).longValue()!=user)throw ApiException.forbidden();return p;}
 public Map<String,Object> managed(long id){var p=find(id);var out=new LinkedHashMap<String,Object>();for(String k:List.of("id","title","description","venueId","approvalStatus","saleStatus"))out.put(k,p.get(k));return out;}
 public Map<String,Object> listManaged(Long owner){return Map.of("items",performances.managed(owner).stream().map(this::managed).toList());}
 @Transactional public Map<String,Object> create(long user,CreatePerformance r){if(r.title()==null||r.title().isBlank()||r.title().length()>255||r.description()==null||r.description().length()>10000)throw ApiException.bad("Invalid performance");var venue=venues.owned(user,r.venueId());return managed(performances.create(user,r.title().trim(),r.description(),r.venueId(),venue.get("name").toString()));}
 @Transactional public Map<String,Object> session(long user,long id,CreateSession r){var p=owned(user,id);if(r.startsAt()==null||!r.startsAt().isAfter(clock.instant())||r.priceKrw()==null||r.priceKrw()<0||r.priceKrw()>1000000000L)throw ApiException.bad("Future start and nonnegative KRW required");long session=performances.session(id,r.startsAt());inventory.initialize(session,venues.seatIds(((Number)p.get("venueId")).longValue()),r.priceKrw());return sessionView(performances.sessions(id,clock.instant()).stream().filter(s->((Number)s.get("id")).longValue()==session).findFirst().orElseThrow());}
 @Transactional public Sale sale(long user,long id,Sale r){owned(user,id);if(r.status()==null||!Set.of("PREPARING","OPEN","CLOSED").contains(r.status())||(r.startsAt()==null)!=(r.endsAt()==null)||(r.startsAt()!=null&&!r.endsAt().isAfter(r.startsAt())))throw ApiException.bad("Invalid sale dates/status");performances.sale(id,r.status(),r.startsAt(),r.endsAt());return r;}
 @Transactional public Map<String,Object> review(long admin,long id,String decision){var p=performances.find(id,true).orElseThrow(ApiException::missing);if(p.get("ownerId")!=null&&((Number)p.get("ownerId")).longValue()==admin)throw ApiException.forbidden();if(!Set.of("APPROVED","REJECTED").contains(decision==null?"":decision))throw ApiException.bad("Invalid review decision");performances.review(id,decision);return managed(id);}
 public Map<String,Object> catalog(String q){if(q.length()>255)throw ApiException.bad("Search too long");return Map.of("items",performances.catalog(q));}
 private Map<String,Object> sessionView(Map<String,Object>s){var out=new LinkedHashMap<>(s);out.put("startsAt",((Timestamp)s.get("startsAt")).toInstant());return out;}
 public Map<String,Object> detail(long id){var p=find(id);if(!"APPROVED".equals(p.get("approvalStatus")))throw ApiException.missing();return Map.of("id",id,"title",p.get("title"),"description",p.get("description"),"venueName",p.get("venueName"),"sessions",performances.sessions(id,clock.instant()).stream().map(this::sessionView).toList());}
 public void visibleSession(long session){Long id=performances.performanceForSession(session);if(id==null)throw ApiException.missing();if(!"APPROVED".equals(find(id).get("approvalStatus")))throw ApiException.missing();}
 @Transactional public void requireSale(long session){Long id=performances.performanceForSession(session);if(id==null)throw ApiException.missing();var p=performances.find(id,true).orElseThrow(ApiException::missing);var now=clock.instant();if(!"APPROVED".equals(p.get("approvalStatus"))||!"OPEN".equals(p.get("saleStatus")))throw ApiException.conflict("SALE_NOT_OPEN");if(p.get("saleStartsAt")!=null&&(now.isBefore(((Timestamp)p.get("saleStartsAt")).toInstant())||!now.isBefore(((Timestamp)p.get("saleEndsAt")).toInstant())))throw ApiException.conflict("SALE_NOT_OPEN");}
}
